// Validates the URL (?url=example.com) – only public domains, no IPs/localhost.
const q = $input.first().json.query || {};
let site = String(q.url || '').trim().replace(/\s/g, '');
if (site && !/^https?:\/\//i.test(site)) site = 'https://' + site;
const m = site.match(/^(https?):\/\/([^\/?#:@]+)(:\d+)?/i);
let url = '';
if (m) {
  const h = m[2].toLowerCase();
  const ok = /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(h) && !/^\d+(\.\d+)+$/.test(h) && !/(^|\.)(localhost|local|internal|lan)$/.test(h);
  if (ok) url = m[1].toLowerCase() + '://' + h + '/';
}
return [{ json: { url, valid: !!url, input: String(q.url || ''), started: Date.now() } }];

// Scores the page on 10 practical checks and builds an HTML report.
const v = $('Validate URL').first().json;
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
let checks = [], score = 0, ms = Date.now() - v.started;
if (v.valid) {
  const r = $input.first().json || {};
  const status = Number(r.statusCode || 0);
  const html = typeof r.body === 'string' ? r.body : (typeof r.data === 'string' ? r.data : '');
  const low = html.toLowerCase();
  const pick = re => { const m = html.match(re); return m ? m[1].replace(/\s+/g, ' ').trim() : ''; };
  const title = pick(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const desc = pick(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i) || pick(/<meta[^>]+content=["']([^"']*)["'][^>]*name=["']description["']/i);
  const h1 = (low.match(/<h1[\s>]/g) || []).length;
  const imgs = (html.match(/<img\b[^>]*>/gi) || []);
  const noAlt = imgs.filter(i => !/\balt=["'][^"']+["']/i.test(i)).length;
  const kb = Math.round(html.length / 1024);
  const up = status >= 200 && status < 400 && html.length > 200;
  checks = [
    ['Reachable', up, up ? `Status ${status}, answered in ~${ms} ms` : 'Page not reachable' + (status ? ` (status ${status})` : '')],
    ['HTTPS', v.url.startsWith('https://') && up, v.url.startsWith('https://') ? 'Encrypted connection' : 'No HTTPS'],
    ['Title tag (10–65 chars)', title.length >= 10 && title.length <= 65, title ? `"${title.slice(0, 70)}" (${title.length})` : 'Missing'],
    ['Meta description (50–160)', desc.length >= 50 && desc.length <= 160, desc ? `${desc.length} characters` : 'Missing'],
    ['Mobile viewport', /<meta[^>]+name=["']viewport["']/i.test(html), /<meta[^>]+name=["']viewport["']/i.test(html) ? 'Set' : 'Missing'],
    ['Exactly one H1', h1 === 1, `${h1} found`],
    ['Image alt texts', imgs.length === 0 || noAlt === 0, imgs.length ? `${imgs.length - noAlt}/${imgs.length} images have alt text` : 'No images'],
    ['Open Graph preview', /property=["']og:image["']/i.test(html), /property=["']og:image["']/i.test(html) ? 'og:image set' : 'No link preview image'],
    ['Language attribute', /<html[^>]+lang=/i.test(html), /<html[^>]+lang=["']?([a-z-]+)/i.test(html) ? 'lang="' + html.match(/<html[^>]+lang=["']?([a-z-]+)/i)[1] + '"' : 'Missing'],
    ['HTML size < 400 KB', kb > 0 && kb < 400, kb + ' KB']
  ].map(([name, ok, info]) => ({ name, ok, info }));
  score = up ? Math.round(100 * checks.filter(c => c.ok).length / checks.length) : 0;
}
const color = score >= 80 ? '#16a34a' : score >= 50 ? '#d97706' : '#dc2626';
const rows = checks.map(c => `<tr><td style="padding:10px 8px;border-bottom:1px solid #eee;width:28px;font-weight:bold;color:${c.ok ? '#16a34a' : '#dc2626'}">${c.ok ? '✓' : '✗'}</td><td style="padding:10px 8px;border-bottom:1px solid #eee"><b>${esc(c.name)}</b><br><span style="color:#6b7280;font-size:14px">${esc(c.info)}</span></td></tr>`).join('');
const page = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Website quick check</title></head>
<body style="margin:0;background:#f3f4f6;font-family:Arial,Helvetica,sans-serif;color:#111827"><div style="max-width:640px;margin:30px auto;background:#fff;border-radius:16px;padding:28px">
<h1 style="margin:0 0 6px;font-size:24px">Website quick check</h1>
${v.valid ? `<p style="margin:0 0 20px;color:#6b7280">${esc(v.url)}</p>
<div style="display:flex;align-items:center;gap:18px;margin-bottom:18px"><div style="font-size:48px;font-weight:bold;color:${color}">${score}</div><div style="color:#6b7280">out of 100<br>${checks.filter(c => c.ok).length} of ${checks.length} checks passed</div></div>
<table style="width:100%;border-collapse:collapse">${rows}</table>`
 : `<p style="color:#dc2626">Please call this URL with <code>?url=yourdomain.com</code> (public domains only).</p>`}
<p style="margin-top:22px;font-size:12px;color:#9ca3af">Automated check · built with n8n</p></div></body></html>`;
return [{ json: { url: v.url, score, checks, html: page } }];
